const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define geometries for central Antakya and Hatay Airport
  // Antakya city center (approximate coordinates)
  const antakyaCenter = ee.Geometry.Point([36.1578, 36.2069]).buffer(2000);

  // Hatay Airport area (approximate coordinates)
  const hatayAirport = ee.Geometry.Point([36.3628, 36.3628]).buffer(2000);

  // Date range for February 14, 2023
  const startDate = '2023-02-14';
  const endDate = '2023-02-15';

  // Load VIIRS Nighttime Day/Night Band data
  const viirs = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
    .filterDate(startDate, endDate);

  // Check if monthly data exists, if not try daily data
  let viirsSize = viirs.size().getInfo();
  console.log(`Monthly VIIRS images found: ${viirsSize}`);

  if (viirsSize === 0) {
    // Try daily data instead
    const viirsDaily = ee.ImageCollection('NOAA/VIIRS/DNB/DAILY_V1')
      .filterDate(startDate, endDate);

    viirsSize = viirsDaily.size().getInfo();
    console.log(`Daily VIIRS images found: ${viirsSize}`);

    if (viirsSize === 0) {
      console.log('No VIIRS data available for February 14, 2023');
      console.log('<answer>C1</answer>');
      return;
    }

    // Use daily data
    const img = viirsDaily.first();

    // Calculate mean radiance for both areas
    const antakyaStats = img.select('avg_rad').reduceRegion({
      reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
      geometry: antakyaCenter,
      scale: 500,
      maxPixels: 1e9
    });

    const airportStats = img.select('avg_rad').reduceRegion({
      reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
      geometry: hatayAirport,
      scale: 500,
      maxPixels: 1e9
    });

    const antakyaRad = antakyaStats.get('avg_rad_mean').getInfo();
    const antakyaCount = antakyaStats.get('avg_rad_count').getInfo();
    const airportRad = airportStats.get('avg_rad_mean').getInfo();
    const airportCount = airportStats.get('avg_rad_count').getInfo();

    console.log(`Antakya Center - Radiance: ${antakyaRad}, Pixels: ${antakyaCount}`);
    console.log(`Hatay Airport - Radiance: ${airportRad}, Pixels: ${airportCount}`);

    // Check for invalid data
    if (antakyaCount === 0 || airportCount === 0) {
      console.log('No valid pixels in one or both areas');
      console.log('<answer>C2</answer>');
      return;
    }

    if (antakyaRad === null || airportRad === null || 
        isNaN(antakyaRad) || isNaN(airportRad)) {
      console.log('Calculation failed - invalid results');
      console.log('<answer>C3</answer>');
      return;
    }

    // Compare radiance values
    if (antakyaRad > airportRad) {
      console.log('Central Antakya is brighter than Hatay Airport area');
      console.log('<answer>A</answer>');
    } else {
      console.log('Hatay Airport area is brighter or equal to central Antakya');
      console.log('<answer>B</answer>');
    }

  } else {
    // Use monthly data
    const img = viirs.first();

    const antakyaStats = img.select('avg_rad').reduceRegion({
      reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
      geometry: antakyaCenter,
      scale: 1000,
      maxPixels: 1e9
    });

    const airportStats = img.select('avg_rad').reduceRegion({
      reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
      geometry: hatayAirport,
      scale: 1000,
      maxPixels: 1e9
    });

    const antakyaRad = antakyaStats.get('avg_rad_mean').getInfo();
    const antakyaCount = antakyaStats.get('avg_rad_count').getInfo();
    const airportRad = airportStats.get('avg_rad_mean').getInfo();
    const airportCount = airportStats.get('avg_rad_count').getInfo();

    console.log(`Antakya Center - Radiance: ${antakyaRad}, Pixels: ${antakyaCount}`);
    console.log(`Hatay Airport - Radiance: ${airportRad}, Pixels: ${airportCount}`);

    if (antakyaCount === 0 || airportCount === 0) {
      console.log('No valid pixels in one or both areas');
      console.log('<answer>C2</answer>');
      return;
    }

    if (antakyaRad === null || airportRad === null || 
        isNaN(antakyaRad) || isNaN(airportRad)) {
      console.log('Calculation failed - invalid results');
      console.log('<answer>C3</answer>');
      return;
    }

    if (antakyaRad > airportRad) {
      console.log('Central Antakya is brighter than Hatay Airport area');
      console.log('<answer>A</answer>');
    } else {
      console.log('Hatay Airport area is brighter or equal to central Antakya');
      console.log('<answer>B</answer>');
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
